UPDATE process_order
SET code_url = #{path}
WHERE order_id = #{orderId}
  AND deleted = FALSE

UPDATE process_order
SET doc_url    = #{path},
    order_name = #{orderName}
WHERE order_id = #{orderId}
  AND deleted = FALSE

UPDATE process_order
SET order_status = #{status}
WHERE order_id = #{orderId}
  AND deleted = FALSE
